import{_ as e,o as d,c as r,a2 as o}from"./chunks/framework.Boholvbs.js";const h=JSON.parse('{"title":"xsync-options(1)","description":"The complete option list, generated from the executable’s own help.","frontmatter":{"title":"xsync-options(1)","description":"The complete option list, generated from the executable’s own help.","manual":"xsync-options(1)","manualName":"Option reference","sectionNumber":"1"},"headers":[],"relativePath":"options.md","filePath":"options.md"}'),s={name:"options.md"};function c(i,t,a,n,l,p){return d(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="xsync-options-1" tabindex="-1">xsync-options(1) <a class="header-anchor" href="#xsync-options-1" aria-label="Permalink to &quot;xsync-options(1)&quot;">​</a></h1><div class="manual-deck"><strong>Option reference</strong><p>The complete option list, generated from the executable’s own help.</p></div><h2 id="source" tabindex="-1">SOURCE <a class="header-anchor" href="#source" aria-label="Permalink to &quot;SOURCE {#source}&quot;">​</a></h2><p>Captured from <code>xs version 0.1.0 protocol version 4 git bd888bdc034c</code>. This is the current native help; delegated options and platform limits are covered in <a href="compatibility.html">compatibility</a>.</p><p><a href="xsync-help.txt" download>Download original help ↗</a>   /   <a href="xs.1" download>Download generated manpage ↗</a></p><h2 id="options-same-meaning-as-rsync" tabindex="-1">OPTIONS (SAME MEANING AS RSYNC) <a class="header-anchor" href="#options-same-meaning-as-rsync" aria-label="Permalink to &quot;OPTIONS (SAME MEANING AS RSYNC) {#options-same-meaning-as-rsync}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">OPTION</th><th scope="col">DESCRIPTION</th></tr></thead><tbody><tr><td><code>-v, --verbose</code></td><td>increase verbosity</td></tr><tr><td><code>-q, --quiet</code></td><td>suppress non-error messages</td></tr><tr><td><code>-c, --checksum</code></td><td>skip based on checksum, not mod-time &amp; size</td></tr><tr><td><code>-a, --archive</code></td><td>archive mode; equals -rlptgoD</td></tr><tr><td><code>-r, --recursive</code></td><td>recurse into directories</td></tr><tr><td><code>-d, --dirs</code></td><td>transfer directories without recursing</td></tr><tr><td><code>-R, --relative</code></td><td>preserve source path components and implied directories</td></tr><tr><td><code>--files-from=FILE</code></td><td>select source names from FILE (&quot;-&quot; reads stdin)</td></tr><tr><td><code>--list-only</code></td><td>list source entries; do not transfer or change DEST</td></tr><tr><td><code>-X, --xattrs</code></td><td>preserve extended attributes (twice includes rsync internals)</td></tr><tr><td><code>-H, --hard-links</code></td><td>preserve hard links within the transferred tree</td></tr><tr><td><code>-S, --sparse</code></td><td>create holes for zero-filled file regions</td></tr><tr><td><code>--link-dest=DIR</code></td><td>reuse unchanged files from a previous snapshot</td></tr><tr><td><code>-l, --links</code></td><td>copy symlinks as symlinks</td></tr><tr><td><code>--safe-links</code></td><td>skip symlinks that point outside the transfer tree</td></tr><tr><td><code>-L, --copy-links</code></td><td>transform symlink into referent file/dir</td></tr><tr><td><code>-p, --perms</code></td><td>preserve permissions</td></tr><tr><td><code>--chmod=CHMOD</code></td><td>change incoming file/directory permissions</td></tr><tr><td><code>-E, --executability</code></td><td>preserve executability of regular files</td></tr><tr><td><code>--fileflags</code></td><td>preserve BSD file flags (macOS)</td></tr><tr><td><code>-o, --owner</code></td><td>preserve owner (super-user only)</td></tr><tr><td><code>-g, --group</code></td><td>preserve group</td></tr><tr><td><code>--chown=USER:GROUP</code></td><td>change destination owner/group (names or IDs)</td></tr><tr><td><code>-D</code></td><td>same as --devices --specials</td></tr><tr><td><code>-A, --acls</code></td><td>preserve ACLs (implies --perms)</td></tr><tr><td><code>-t, --times</code></td><td>preserve modification times</td></tr><tr><td><code>-U, --atimes</code></td><td>preserve file access times (twice enables --open-noatime)</td></tr><tr><td><code>-N, --crtimes</code></td><td>preserve creation times (macOS)</td></tr><tr><td><code>--open-noatime</code></td><td>avoid read access-time updates where supported</td></tr><tr><td><code>-O, --omit-dir-times</code></td><td>omit directory modification/access/creation times</td></tr><tr><td><code>-J, --omit-link-times</code></td><td>omit symlink modification/access/creation times</td></tr><tr><td><code>-n, --dry-run</code></td><td>perform a trial run with no changes made</td></tr><tr><td><code>-W, --whole-file</code></td><td>send the whole file; disable resume and block matching</td></tr><tr><td><code>--no-whole-file</code></td><td>enable verified-prefix resume again</td></tr><tr><td><code>-x, --one-file-system</code></td><td>don&#39;t cross filesystem boundaries</td></tr><tr><td><code>-e, --rsh=COMMAND</code></td><td>specify the remote shell to use</td></tr><tr><td><code>--rsync-path=PROGRAM specify the xs to run on the remote machine</code></td><td></td></tr><tr><td><code>--no-fallback</code></td><td>fail instead of re-executing rsync for missing support</td></tr><tr><td><code>--fallback</code></td><td>enable fallback (overrides XSYNC_FALLBACK=0)</td></tr><tr><td><code>--existing</code></td><td>skip creating new files on receiver</td></tr><tr><td><code>--ignore-existing</code></td><td>skip updating files that exist on receiver</td></tr><tr><td><code>--delete</code></td><td>delete extraneous files from dest dirs</td></tr><tr><td><code>--delete-after</code></td><td>scan deletions and merge files after transfer</td></tr><tr><td><code>-m, --prune-empty-dirs</code></td><td>omit empty directory chains from the file list</td></tr><tr><td><code>--delete-excluded</code></td><td>also delete excluded files from dest dirs</td></tr><tr><td><code>--ignore-errors</code></td><td>delete even when the sender encountered I/O errors</td></tr><tr><td><code>--max-delete=NUM</code></td><td>delete at most NUM entries (exit 25 if exceeded)</td></tr><tr><td><code>--force</code></td><td>force deletion of dirs even if not empty</td></tr><tr><td><code>--max-size=SIZE</code></td><td>don&#39;t transfer any file larger than SIZE</td></tr><tr><td><code>--min-size=SIZE</code></td><td>don&#39;t transfer any file smaller than SIZE</td></tr><tr><td><code>--bwlimit=RATE</code></td><td>limit bytes sent/copied per second (bare RATE: KiB/s)</td></tr><tr><td><code>--timeout=SECONDS</code></td><td>remote idle I/O timeout (0 disables; exits with code 30)</td></tr><tr><td><code>--partial</code></td><td>keep partially transferred files</td></tr><tr><td><code>--inplace</code></td><td>update destination files in-place</td></tr><tr><td><code>--mkpath</code></td><td>create the destination&#39;s path component</td></tr><tr><td><code>--numeric-ids</code></td><td>don&#39;t map uid/gid values by user/group name</td></tr><tr><td><code>-u, --update</code></td><td>skip files that are newer on the receiver</td></tr><tr><td><code>-I, --ignore-times</code></td><td>don&#39;t skip files that match size and time</td></tr><tr><td><code>--size-only</code></td><td>skip files that match in size</td></tr><tr><td><code>-@, --modify-window=NUM</code></td><td>set the accuracy for mod-time comparisons</td></tr><tr><td><code>-z, --compress</code></td><td>compress file data during the transfer (zstd)</td></tr><tr><td><code>--compress-level=NUM explicitly set compression level</code></td><td></td></tr><tr><td><code>-f, --filter=RULE</code></td><td>add a file-filtering RULE</td></tr><tr><td><code>-F</code></td><td>merge .rsync-filter files (twice also excludes them)</td></tr><tr><td><code>-C, --cvs-exclude</code></td><td>exclude CVS defaults and .cvsignore patterns</td></tr><tr><td><code>--exclude=PATTERN</code></td><td>exclude files matching PATTERN</td></tr><tr><td><code>--exclude-from=FILE</code></td><td>read exclude patterns from FILE</td></tr><tr><td><code>--include=PATTERN</code></td><td>don&#39;t exclude files matching PATTERN</td></tr><tr><td><code>--include-from=FILE</code></td><td>read include patterns from FILE</td></tr><tr><td><code>-0, --from0</code></td><td>use NUL delimiters in list and filter merge files</td></tr><tr><td><code>--stats</code></td><td>give some file-transfer stats</td></tr><tr><td><code>-h, --human-readable</code></td><td>use 1000-based units (-hh uses 1024)</td></tr><tr><td><code>--progress[=json]</code></td><td>show progress (default on terminals), or JSON events</td></tr><tr><td><code>--no-progress</code></td><td>suppress progress; XSYNC_PROGRESS=0 also disables it</td></tr><tr><td><code>-P</code></td><td>same as --partial --progress</td></tr><tr><td><code>-i, --itemize-changes</code></td><td>output a change-summary for all updates</td></tr><tr><td><code>-8, --8-bit-output</code></td><td>retain high bytes in names; escape unsafe control bytes</td></tr><tr><td><code>--out-format=FORMAT</code></td><td>file lines: %i %n %L %l %o %f %b %t %% (optional width)</td></tr><tr><td><code>--log-file=FILE</code></td><td>append the same stdout stream to FILE</td></tr><tr><td><code>--version, --help</code></td><td></td></tr></tbody></table></div><h2 id="documented-compatibility-no-ops" tabindex="-1">DOCUMENTED COMPATIBILITY NO-OPS <a class="header-anchor" href="#documented-compatibility-no-ops" aria-label="Permalink to &quot;DOCUMENTED COMPATIBILITY NO-OPS {#documented-compatibility-no-ops}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">OPTION</th><th scope="col">DESCRIPTION</th></tr></thead><tbody><tr><td><code>-s, --protect-args, --secluded-args</code></td><td> paths always travel as protocol data, not shell text</td></tr><tr><td><code>--blocking-io, --no-blocking-io</code></td><td> transport polling handles either pipe mode internally</td></tr><tr><td><code>--no-motd</code></td><td>no daemon transport or daemon greeting exists</td></tr></tbody></table></div><h2 id="xs-extensions" tabindex="-1">XS EXTENSIONS <a class="header-anchor" href="#xs-extensions" aria-label="Permalink to &quot;XS EXTENSIONS {#xs-extensions}&quot;">​</a></h2><div class="manual-table-wrap"><table><thead><tr><th scope="col">OPTION</th><th scope="col">DESCRIPTION</th></tr></thead><tbody><tr><td><code>--install=HOST</code></td><td>explicitly install the matching release at ~/.local/bin refuses newer versions unless --force is supplied</td></tr><tr><td><code>-j, --jobs=N</code></td><td>number of worker threads (default: performance cores)</td></tr><tr><td><code>--no-clone</code></td><td>always copy file data, even where a copy-on-write clone (APFS, same volume, with -pt) would be possible</td></tr><tr><td><code>--atomic</code></td><td>create new files via temp file + rename (default)</td></tr><tr><td><code>--no-atomic</code></td><td>create new byte-copied files directly (fewer renames; a crash can leave truncated files under final names)</td></tr></tbody></table></div>',11)])])}const f=e(s,[["render",c]]);export{h as __pageData,f as default};
